package com.roomreserved.controller;
import com.roomreserved.model.*; import com.roomreserved.repo.*; import com.roomreserved.service.BookingService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.core.Authentication; import java.time.*; import java.math.BigDecimal; import java.util.*;
@Controller
public class WebController {
 private final RoomRepository rooms; private final UserRepository users; private final BookingRepository bookings; private final PromoRepository promos; private final ReviewRepository reviews; private final PasswordEncoder encoder; private final BookingService bookingService;
 public WebController(RoomRepository r,UserRepository u,BookingRepository b,PromoRepository p,ReviewRepository v,PasswordEncoder e,BookingService bs){rooms=r;users=u;bookings=b;promos=p;reviews=v;encoder=e;bookingService=bs;}
 @GetMapping("/") public String home(Model m){if(rooms.count()==0) seed(); m.addAttribute("rooms",rooms.findByActiveTrue()); return "index";}
 private void seed(){String[] names={"Coastal King Suite","Garden Deluxe Room","City View Studio"}; String[] imgs={"https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1617104678098-de229db51175?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=85"}; String[] descriptions={"A calm, generously sized suite with layered textures and room to settle in after a day out.","A warm, light-filled room with natural finishes and a quieter pace in mind.","A polished city base with practical comforts and a welcoming, understated feel."}; int[] prices={5200,3600,2900}; for(int i=0;i<names.length;i++){Room r=new Room();r.setName(names[i]);r.setDescription(descriptions[i]);r.setPricePerNight(BigDecimal.valueOf(prices[i]));r.setImageUrl(imgs[i]);r.setAmenities("Wi-Fi · Air conditioning · Private bathroom · Breakfast option");rooms.save(r);}}
 @GetMapping("/login") public String login(){return "login";}
 @GetMapping("/register") public String register(){return "register";}
 @PostMapping("/register") public String registerPost(@RequestParam String fullName,@RequestParam String email,@RequestParam String password,Model m){if(password.length()<8){m.addAttribute("error","Password must be at least 8 characters.");return "register";} if(users.findByEmail(email).isPresent()){m.addAttribute("error","That email is already registered.");return "register";} AppUser u=new AppUser();u.setFullName(fullName);u.setEmail(email.toLowerCase(Locale.ROOT));u.setPassword(encoder.encode(password));users.save(u);return "redirect:/login?registered";}
 @GetMapping("/rooms/{id}") public String room(@PathVariable Long id,Model m){Room r=rooms.findById(id).orElseThrow();m.addAttribute("room",r);m.addAttribute("reviews",reviews.findByRoomIdOrderByCreatedAtDesc(id));return "room";}
 @GetMapping("/availability") @ResponseBody public Map<String,Object> availability(@RequestParam Long roomId,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate checkIn,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate checkOut){Map<String,Object> x=new HashMap<>();Room room=rooms.findById(roomId).orElse(null); long reserved=(room!=null&&checkIn!=null&&checkOut!=null&&checkOut.isAfter(checkIn))?bookings.countConflicts(roomId,checkIn,checkOut):Long.MAX_VALUE; x.put("available",room!=null&&room.isActive()&&checkIn!=null&&checkOut!=null&&checkIn.isAfter(LocalDate.now().minusDays(1))&&checkOut.isAfter(checkIn)&&reserved<room.getInventoryCount()); x.put("inventoryCount",room==null?0:room.getInventoryCount()); x.put("reservedQuantity",reserved==Long.MAX_VALUE?null:reserved);return x;}
 @GetMapping("/bookings") public String myBookings(Authentication auth,Model m){m.addAttribute("bookings",bookings.findByUserEmailOrderByCreatedAtDesc(auth.getName()));return "bookings";}
 @PostMapping("/bookings") public String book(@RequestParam Long roomId,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate checkIn,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate checkOut,@RequestParam(required=false) String promoCode,Authentication auth,Model m){
  try { AppUser user=users.findByEmail(auth.getName()).orElseThrow(); bookingService.createHold(roomId,checkIn,checkOut,promoCode,user,1,2,0); return "redirect:/bookings?holdCreated"; }
  catch(IllegalArgumentException ex){m.addAttribute("error",ex.getMessage());m.addAttribute("rooms",rooms.findByActiveTrue());return "index";}
 }
 @PostMapping("/bookings/{id}/cancel") public String cancel(@PathVariable Long id,Authentication auth){Booking b=bookings.findById(id).orElseThrow();if(b.getUser().getEmail().equals(auth.getName())&&b.getCheckIn().isAfter(LocalDate.now()))b.setStatus("CANCELLED");bookings.save(b);return "redirect:/bookings";}
 @PostMapping("/rooms/{id}/reviews") public String review(@PathVariable Long id,@RequestParam int stars,@RequestParam String comment,Authentication auth){if(stars>=1&&stars<=5){Review r=new Review();r.setUser(users.findByEmail(auth.getName()).orElseThrow());r.setRoom(rooms.findById(id).orElseThrow());r.setStars(stars);r.setComment(comment);reviews.save(r);}return "redirect:/rooms/"+id;}
 @GetMapping("/admin") public String admin(Model m){m.addAttribute("rooms",rooms.findAll());m.addAttribute("bookings",bookings.findAllByOrderByCreatedAtDesc());m.addAttribute("users",users.count());return "admin";}
 @PostMapping("/admin/rooms") public String addRoom(@RequestParam String name,@RequestParam BigDecimal pricePerNight,@RequestParam String description,@RequestParam(required=false) String imageUrl,@RequestParam(required=false) String amenities,@RequestParam(defaultValue="2") int capacity){Room r=new Room();r.setName(name);r.setPricePerNight(pricePerNight);r.setDescription(description);r.setImageUrl(imageUrl);r.setAmenities(amenities);r.setCapacity(capacity);rooms.save(r);return "redirect:/admin";}
 @PostMapping("/admin/bookings/{id}/cancel") public String adminCancel(@PathVariable Long id){Booking b=bookings.findById(id).orElseThrow();b.setStatus("CANCELLED");bookings.save(b);return "redirect:/admin";}
 @PostMapping("/admin/promos") public String addPromo(@RequestParam String code,@RequestParam BigDecimal discountPercent,@RequestParam(required=false) @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate expiresAt){PromoCode p=new PromoCode();p.setCode(code.toUpperCase(Locale.ROOT));p.setDiscountPercent(discountPercent);p.setExpiresAt(expiresAt);promos.save(p);return "redirect:/admin";}
}
